//! Of overlapping CRG records for one purpose, the last in the file wins
//! (rule `road.crg.use_last_entry`), and a junction's come before its
//! roads'.
//!
//! `tests/data/crg_order.xodr` is generated by `crg_order.py`. Each
//! elevation record there lifts the road by its own `zOffset` over one file,
//! so the height above the grid names the record that answered. Friction
//! records use a flat file each, so the friction names it.

use opencrg::CrgGrid;
use xodr::{load_file, RoadNetwork, RoadPosition, RoadSurface, SurfaceHint, SurfaceSample};

/// A CRG file, `length` metres long and `2 * half` wide on a straight
/// reference line from the origin, with `value(u, v)` at each grid point.
fn grid(length: f64, half: f64, value: impl Fn(f64, f64) -> f64) -> CrgGrid {
    let step = 0.5;
    let columns = (2.0 * half / step) as usize + 1;
    let rows = (length / step) as usize + 1;
    let mut text = format!(
        "$ROAD_CRG\nREFERENCE_LINE_INCREMENT = {step}\nLONG_SECTION_V_RIGHT = {}\n\
         LONG_SECTION_V_INCREMENT = {step}\n$\n$KD_Definition\n#:LRFI\n",
        -half
    );
    for c in 0..columns {
        text += &format!("D:long section {},m\n", c + 1);
    }
    text += "$\n$$$$\n";
    for r in 0..rows {
        for c in 0..columns {
            let z = value(r as f64 * step, -half + c as f64 * step);
            text += &format!("{z:10.6}");
            if c % 8 == 7 || c == columns - 1 {
                text += "\n";
            }
        }
    }
    CrgGrid::from_bytes(text.as_bytes()).expect("the generated CRG loads")
}

fn load(name: &str) -> Option<CrgGrid> {
    match name {
        "elev.crg" => Some(grid(100.0, 20.0, |u, v| 0.01 * u + 0.02 * v)),
        "f1.crg" => Some(grid(100.0, 20.0, |_, _| 0.3)),
        "f2.crg" => Some(grid(100.0, 20.0, |_, _| 0.8)),
        _ => None,
    }
}

fn network() -> RoadNetwork {
    load_file("tests/data/crg_order.xodr").unwrap()
}

/// The surface at road `road`, `s` along it and 1.75 m to its right.
fn sample(net: &RoadNetwork, surface: &RoadSurface, road: &str, s: f64) -> SurfaceSample {
    let id = net.road_by_od_id(road).expect("the road").id();
    let point = net
        .road_point(RoadPosition {
            road: id,
            s,
            t: -1.75,
        })
        .expect("on the road");
    surface
        .sample(
            f64::from(point.x),
            f64::from(point.y),
            &mut SurfaceHint::default(),
        )
        .expect("on the road")
}

/// The `zOffset` of the elevation record that answered.
fn lift(sample: &SurfaceSample) -> f64 {
    sample.z - sample.crg_height.expect("an elevation record answered")
}

#[test]
fn the_last_elevation_record_in_the_file_wins_where_they_overlap() {
    let net = network();
    let mesh = net.surface_mesh();
    let surface = RoadSurface::new(&net, &mesh, load);
    // Road 1 lists 0.1 (0 to 60 m), 0.2 (20 to 80 m), then 0.3 (40 to 100 m).
    for (s, want) in [
        (10.0, 0.1),
        (30.0, 0.2),
        (50.0, 0.3),
        (70.0, 0.3),
        (90.0, 0.3),
    ] {
        let got = lift(&sample(&net, &surface, "1", s));
        assert!(
            (got - want).abs() < 1e-5,
            "road 1, s {s}: lift {got}, want {want}"
        );
    }
}

#[test]
fn file_order_decides_not_which_record_starts_last() {
    let net = network();
    let mesh = net.surface_mesh();
    let surface = RoadSurface::new(&net, &mesh, load);
    // Road 2 lists the same records as road 1 the other way round.
    for (s, want) in [
        (10.0, 0.1),
        (30.0, 0.1),
        (50.0, 0.1),
        (70.0, 0.2),
        (90.0, 0.3),
    ] {
        let got = lift(&sample(&net, &surface, "2", s));
        assert!(
            (got - want).abs() < 1e-5,
            "road 2, s {s}: lift {got}, want {want}"
        );
    }
}

#[test]
fn the_last_friction_record_in_the_file_wins_where_they_overlap() {
    let net = network();
    let mesh = net.surface_mesh();
    let surface = RoadSurface::new(&net, &mesh, load);
    // 0.3 from 0 to 50 m, then 0.8 from 30 to 100 m.
    for road in ["1", "2"] {
        for (s, want) in [
            (10.0, 0.3),
            (20.0, 0.3),
            (40.0, 0.8),
            (60.0, 0.8),
            (90.0, 0.8),
        ] {
            let got = sample(&net, &surface, road, s)
                .friction
                .expect("friction answered");
            assert!(
                (got - want).abs() < 1e-5,
                "road {road}, s {s}: {got}, want {want}"
            );
        }
    }
}

#[test]
fn a_junctions_last_record_beats_its_roads_and_its_other_records() {
    let net = network();
    let mesh = net.surface_mesh();
    let surface = RoadSurface::new(&net, &mesh, load);
    // Junction 9 lists 0.6 then 0.7. Road 1000 has a record of 0.5 of its own.
    for road in ["1000", "1001"] {
        let got = lift(&sample(&net, &surface, road, 10.0));
        assert!((got - 0.7).abs() < 1e-5, "road {road}: lift {got}");
    }
}
